#pragma once
#define BATTERIES_ASYNC_TRANSFER_HPP

#include <batteries/async/io_result.hpp>
#include <batteries/async/task.hpp>
#include <batteries/buffer.hpp>
#include <batteries/int_types.hpp>
#include <batteries/status.hpp>
#include <batteries/utility.hpp>

#include <boost/range/iterator_range.hpp>
#include <boost/range/join.hpp>

#include <type_traits>

namespace batt {

//==#==========+==+=+=++=+++++++++++-+-+--+----- --- -- -  -  -   -
//
template <typename Op, typename AsyncStream, typename BuffersT>
BATT_ALWAYS_INLINE Status await_transfer_all_impl(AsyncStream& stream, u64 offset,
                                                  BuffersT&& buffers) noexcept
{
    auto iter = boost::asio::buffer_sequence_begin(buffers);
    auto last = boost::asio::buffer_sequence_end(buffers);

    using Iter = std::decay_t<decltype(iter)>;

    if (iter == last) {
        return OkStatus();
    }

    typename Op::SingleBuffer current_buffer = *iter;
    ++iter;

    while (iter != last) {
        IOResult<usize> result = Task::await<IOResult<usize>>([&](auto&& handler) {
            Op::async_transfer_some_at(
                stream, offset,
                boost::range::join(boost::make_iterator_range(&current_buffer, (&current_buffer) + 1),
                                   boost::make_iterator_range(iter, last)),
                BATT_FORWARD(handler));
        });
        BATT_REQUIRE_OK(result);

        offset += *result;
        usize remaining = *result;
        while (remaining != 0) {
            const usize step_size = std::min(remaining, current_buffer.size());
            current_buffer += step_size;
            remaining -= step_size;
            if (current_buffer.size() == 0) {
                ++iter;
                if (iter == last) {
                    break;
                }
                current_buffer = *iter;
            }
        }
    }

    while (current_buffer.size() != 0) {
        IOResult<usize> result = Task::await<IOResult<usize>>([&](auto&& handler) {
            Op::async_transfer_some_at(stream, offset, current_buffer, BATT_FORWARD(handler));
        });
        BATT_REQUIRE_OK(result);
        current_buffer += *result;
    }

    return OkStatus();
}

}  // namespace batt
